from copy import copy
from decimal import Decimal, InvalidOperation
from datetime import datetime
import re
from openpyxl import load_workbook, Workbook
from openpyxl.utils import get_column_letter
from docx import Document

PLAN = '/root/Cycle_Plan.xlsx'
EVENTS = '/root/Count_Event_Log.xlsx'
TEMPLATE = '/root/Cycle_Template.xlsx'
OUT_XLSX = '/root/Cycle_Count_Variance_Audit.xlsx'
OUT_DOCX = '/root/Cycle_Count_Variance_Brief.docx'

BASE_HEADERS = [
    'Facility', 'Session ID', 'Bin ID', 'Product ID',
    'Expected Qty', 'Allowed Variance', 'Approval Needed'
]
FORMATTED_HEADERS = BASE_HEADERS + [
    'Missing Final Count', 'Approval Gap', 'Total Errors', 'Error Summary'
]
SUMMARY_HEADERS = [
    'Facility', 'Session ID', 'Missing Final Counts', 'Approval Gaps', 'Total Errors'
]
KEY_HEADERS = ['Facility', 'Session ID', 'Bin ID']

def norm_blank(v):
    if v is None:
        return None
    if isinstance(v, str) and v.strip() == '':
        return None
    return v

def to_decimal(v):
    if v is None or (isinstance(v, str) and v.strip() == ''):
        return None
    try:
        return Decimal(str(v).strip())
    except (InvalidOperation, ValueError):
        return None

def parse_time(v):
    if v is None:
        return None
    if isinstance(v, datetime):
        return v
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return None
        # Handle common ISO-ish strings, including trailing Z.
        try:
            return datetime.fromisoformat(s.replace('Z', '+00:00'))
        except ValueError:
            pass
        for fmt in ('%Y-%m-%d %H:%M:%S', '%m/%d/%Y %H:%M:%S', '%m/%d/%Y %H:%M'):
            try:
                return datetime.strptime(s, fmt)
            except ValueError:
                pass
    return None

def copy_sheet_exact(src_ws, dst_ws):
    # Values and cell-level formatting
    for row in src_ws.iter_rows():
        for src_cell in row:
            dst_cell = dst_ws[src_cell.coordinate]
            dst_cell.value = src_cell.value
            if src_cell.has_style:
                dst_cell._style = copy(src_cell._style)
            if src_cell.number_format:
                dst_cell.number_format = src_cell.number_format
            if src_cell.font:
                dst_cell.font = copy(src_cell.font)
            if src_cell.fill:
                dst_cell.fill = copy(src_cell.fill)
            if src_cell.border:
                dst_cell.border = copy(src_cell.border)
            if src_cell.alignment:
                dst_cell.alignment = copy(src_cell.alignment)
            if src_cell.protection:
                dst_cell.protection = copy(src_cell.protection)
            if src_cell.comment:
                dst_cell.comment = copy(src_cell.comment)
            if src_cell.hyperlink:
                dst_cell._hyperlink = copy(src_cell.hyperlink)
    # Merged cells
    for merged in src_ws.merged_cells.ranges:
        dst_ws.merge_cells(str(merged))
    # Dimensions and sheet properties
    for key, dim in src_ws.row_dimensions.items():
        dst_ws.row_dimensions[key] = copy(dim)
    for key, dim in src_ws.column_dimensions.items():
        dst_ws.column_dimensions[key] = copy(dim)
    dst_ws.sheet_format = copy(src_ws.sheet_format)
    dst_ws.sheet_properties = copy(src_ws.sheet_properties)
    dst_ws.page_margins = copy(src_ws.page_margins)
    dst_ws.page_setup = copy(src_ws.page_setup)
    dst_ws.print_options = copy(src_ws.print_options)
    dst_ws.sheet_view = copy(src_ws.sheet_view)
    dst_ws.freeze_panes = src_ws.freeze_panes
    if src_ws.auto_filter.ref:
        dst_ws.auto_filter.ref = src_ws.auto_filter.ref
    if src_ws.print_area:
        dst_ws.print_area = src_ws.print_area

def sheet_to_records(ws):
    rows = list(ws.iter_rows(values_only=True))
    if not rows:
        return [], []
    headers = [str(h).strip() if h is not None else '' for h in rows[0]]
    records = []
    for row in rows[1:]:
        if all(v is None for v in row):
            continue
        rec = {headers[i]: row[i] if i < len(row) else None for i in range(len(headers))}
        records.append(rec)
    return headers, records

def validate_input_headers(headers, required, source):
    missing = [h for h in required if h not in headers]
    if missing:
        raise ValueError(f'{source} missing required headers: {missing}; found {headers}')

def choose_timestamp_header(headers):
    candidates = ['Event Time', 'Timestamp', 'Event Timestamp', 'Count Time', 'Created At', 'Date Time']
    for c in candidates:
        if c in headers:
            return c
    for h in headers:
        lower = h.lower()
        if 'time' in lower or 'timestamp' in lower or 'date' in lower:
            return h
    return None

def build_kept_finals(event_headers, event_records):
    validate_input_headers(event_headers, ['Facility', 'Session ID', 'Bin ID', 'Event Type', 'Count Qty'], 'Count event log')
    ts_header = choose_timestamp_header(event_headers)
    kept = {}
    for idx, rec in enumerate(event_records):
        if str(rec.get('Event Type') or '').strip().upper() != 'FINAL':
            continue
        # Drop rows where Facility, Session ID, Bin ID, or Count Qty is blank/NaN.
        if any(norm_blank(rec.get(h)) is None for h in ['Facility', 'Session ID', 'Bin ID', 'Count Qty']):
            continue
        key = (str(rec['Facility']), str(rec['Session ID']), str(rec['Bin ID']))
        parsed_ts = parse_time(rec.get(ts_header)) if ts_header else None
        candidate = {'record': rec, 'file_order': idx, 'timestamp': parsed_ts}
        old = kept.get(key)
        if old is None:
            kept[key] = candidate
        elif ts_header and parsed_ts is not None and old.get('timestamp') is not None:
            if parsed_ts >= old['timestamp']:
                kept[key] = candidate
        elif ts_header and parsed_ts is not None and old.get('timestamp') is None:
            kept[key] = candidate
        elif (not ts_header) or (parsed_ts is None and old.get('timestamp') is None):
            if idx >= old['file_order']:
                kept[key] = candidate
        else:
            # Existing has a parseable timestamp, candidate does not; keep existing.
            pass
    return kept, ts_header

def main():
    template_wb = load_workbook(TEMPLATE)
    if 'Overview' not in template_wb.sheetnames:
        raise ValueError('Template does not contain Overview sheet')
    source_overview = template_wb['Overview']

    plan_wb = load_workbook(PLAN, data_only=True)
    plan_ws = plan_wb[plan_wb.sheetnames[0]]
    plan_headers, plan_records = sheet_to_records(plan_ws)
    validate_input_headers(plan_headers, BASE_HEADERS, 'Cycle plan')

    events_wb = load_workbook(EVENTS, data_only=True)
    event_ws = events_wb[events_wb.sheetnames[0]]
    event_headers, event_records = sheet_to_records(event_ws)
    kept_finals, ts_header = build_kept_finals(event_headers, event_records)

    out_wb = Workbook()
    # Remove default sheet and create sheets in exact required order.
    default = out_wb.active
    out_wb.remove(default)
    overview_ws = out_wb.create_sheet('Overview')
    raw_ws = out_wb.create_sheet('RawData')
    formatted_ws = out_wb.create_sheet('Formatted Data')
    summary_ws = out_wb.create_sheet('Summary')

    copy_sheet_exact(source_overview, overview_ws)

    # RawData: exact plan headers and data rows in same order.
    raw_ws.append(plan_headers)
    for rec in plan_records:
        raw_ws.append([rec.get(h) for h in plan_headers])

    # Formatted Data: first 7 plan columns plus computed checks.
    formatted_ws.append(FORMATTED_HEADERS)
    formatted_rows_written = []
    for rec in plan_records:
        base_values = [rec.get(h) for h in BASE_HEADERS]
        key = (str(rec.get('Facility')), str(rec.get('Session ID')), str(rec.get('Bin ID')))
        final = kept_finals.get(key)
        missing = 1 if final is None else 0
        approval_gap = 0
        if final is not None and str(rec.get('Approval Needed') or '').strip().upper() == 'YES':
            expected = to_decimal(rec.get('Expected Qty'))
            allowed = to_decimal(rec.get('Allowed Variance'))
            count_qty = to_decimal(final['record'].get('Count Qty'))
            if expected is not None and allowed is not None and count_qty is not None:
                approval_gap = 1 if abs(expected - count_qty) > allowed else 0
        total = missing + approval_gap
        labels = []
        if missing:
            labels.append('Missing Final Count')
        if approval_gap:
            labels.append('Approval Gap')
        error_summary = ', '.join(labels) if labels else 'None'
        out_row = base_values + [missing, approval_gap, total, error_summary]
        formatted_ws.append(out_row)
        formatted_rows_written.append(out_row)

    # Summary aggregates from the Formatted Data values just written.
    summary_ws.append(SUMMARY_HEADERS)
    aggregates = {}
    for row in formatted_ws.iter_rows(min_row=2, values_only=True):
        rec = dict(zip(FORMATTED_HEADERS, row))
        key = (str(rec['Facility']), str(rec['Session ID']))
        if key not in aggregates:
            aggregates[key] = {'missing': 0, 'gaps': 0, 'total': 0}
        aggregates[key]['missing'] += int(rec['Missing Final Count'] or 0)
        aggregates[key]['gaps'] += int(rec['Approval Gap'] or 0)
        aggregates[key]['total'] += int(rec['Total Errors'] or 0)
    groups = [
        (facility, session, vals['missing'], vals['gaps'], vals['total'])
        for (facility, session), vals in aggregates.items() if vals['total'] > 0
    ]
    groups.sort(key=lambda x: (x[0], x[1]))
    for g in groups:
        summary_ws.append(list(g))
    total_missing = sum(g[2] for g in groups)
    total_gaps = sum(g[3] for g in groups)
    total_errors = sum(g[4] for g in groups)
    summary_ws.append(['Grand Total', '-', total_missing, total_gaps, total_errors])

    # Basic formatting for generated data sheets (does not affect Overview preservation).
    for ws in [raw_ws, formatted_ws, summary_ws]:
        for col_idx in range(1, ws.max_column + 1):
            letter = get_column_letter(col_idx)
            max_len = 0
            for cell in ws[letter]:
                max_len = max(max_len, len(str(cell.value)) if cell.value is not None else 0)
            ws.column_dimensions[letter].width = min(max_len + 2, 40)
        ws.freeze_panes = 'A2'

    out_wb.save(OUT_XLSX)

    # Derive top-2 from Summary aggregates before docx, using required sort.
    top_rows = sorted(groups, key=lambda x: (-x[4], -x[2], x[0], x[1]))[:2]
    top_pairs = [f'{facility}-{session}' for facility, session, *_ in top_rows]
    top_descriptions = [f'{facility}-{session} (Facility {facility} Session {session})' for facility, session, *_ in top_rows]
    if len(top_rows) < 2:
        print(f'WARNING: fewer than 2 groups with Total Errors > 0; available={len(top_rows)}')
    if top_descriptions:
        if len(top_descriptions) == 1:
            focus_text = top_descriptions[0]
        else:
            focus_text = ' and '.join([', '.join(top_descriptions[:-1]), top_descriptions[-1]]).strip(', ')
    else:
        focus_text = 'no Facility/Session combinations with exceptions'

    doc = Document()
    doc.add_heading('Cycle Count Variance Audit Brief', level=1)
    paragraph = (
        'Missing Final Count means no FINAL count event was recorded for a planned bin. '
        'Approval Gap means a final count exists, approval was required, and the absolute variance from expected exceeded the allowed tolerance. '
        f'The audit identified {total_missing} Missing Final Counts, {total_gaps} Approval Gaps, and {total_errors} Total Errors overall. '
        f'High-priority focus areas include {focus_text}, which account for the highest exception counts. '
        'Recommended next steps are to re-count bins missing FINAL events, route flagged variances to supervisor approval, and review session closeout controls before inventory is finalized.'
    )
    doc.add_paragraph(paragraph)
    doc.save(OUT_DOCX)

    print('Generated:', OUT_XLSX)
    print('Generated:', OUT_DOCX)
    print('Event timestamp header used:', ts_header)
    print('Summary groups:', groups)
    print('Grand totals:', total_missing, total_gaps, total_errors)
    print('Top pairs:', top_pairs)

if __name__ == '__main__':
    main()
